public void runProcess(FTDBookInventoryMultiselectUpdationDataContract _dataContract)
{
    ListIterator literator = new ListIterator(_dataContract.parmBookRecIdList());

    while(literator.more())
    {
        this.runRecord(FTDBookTable::findRecId(literator.value()), _dataContract.parmNewQty());
        literator.next();
    }

}

private void runRecord(FTDBookTable _book, Qty _newQty)
{
    Qty currentInventory = _book.currentInventory();

    Qty newTransactionQtyNeeded = _newQty - currentInventory;

    if (newTransactionQtyNeeded == 0)
    {
        return;
    }

    FTDBookInventoryTransaction inventoryTransaction;

    inventoryTransaction.TransId = guid2Str(newGuid());
    inventoryTransaction.Book = _book.RecId;
    inventoryTransaction.Qty = newTransactionQtyNeeded;

    if (inventoryTransaction.validateWrite())
    {
        inventoryTransaction.insert();
        Info(strFmt("created Inventory Transaction for book %1, with Qty %2", _book.Id, inventoryTransaction.Qty));
    }
    else
    {
        throw Exception::Error;
    }
}
